import socket, struct, json

def dns_query(name, server="127.0.0.11"):
    tid = 0x1234
    flags = 0x0100
    q = struct.pack(">HHHHHH", tid, flags, 1, 0, 0, 0)
    for part in name.split("."):
        q += bytes([len(part)]) + part.encode()
    q += b"\x00" + struct.pack(">HH", 1, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(2)
    s.sendto(q, (server, 53))
    try:
        data, _ = s.recvfrom(4096)
    except socket.timeout:
        return None
    ancount = struct.unpack(">H", data[6:8])[0]
    rcode = struct.unpack(">H", data[2:4])[0] & 0xF
    # parse answers (skip question)
    i = 12
    while data[i] != 0:
        i += data[i] + 1
    i += 5
    answers = []
    for _ in range(ancount):
        # skip name (may be pointer)
        while True:
            b = data[i]
            if b == 0:
                i += 1; break
            if b & 0xC0:
                i += 2; break
            i += b + 1
        rtype, rclass, ttl, rdlen = struct.unpack(">HHIH", data[i:i+10])
        i += 10
        rdata = data[i:i+rdlen]; i += rdlen
        if rtype == 1:
            answers.append(socket.inet_ntoa(rdata))
        else:
            answers.append(f"type{rtype}:{rdata[:40]!r}")
    return rcode, answers

for name in ["commons.local", "prices.internal", "internal", "host.docker.internal", "gateway.docker.internal"]:
    try:
        print(name, "->", dns_query(name))
    except Exception as e:
        print(name, "ERR", e)
EOF"}

